"use client";
import {useEffect,useState} from "react";
type Assignment={offeringId:string;packageId:string};
type Document={id:string;title:string;archived:boolean;assignments:Assignment[];signatures:{id:string;signerName:string;signedAt:string;quoteId:string}[]};
type Service={id:string;title:string;packages:{id:string;name:string}[]};
export function BusinessWaiverManager({businessId}:{businessId:string}){
 const [documents,setDocuments]=useState<Document[]>([]),[services,setServices]=useState<Service[]>([]),[error,setError]=useState(""),[pending,setPending]=useState(false),[loaded,setLoaded]=useState(false);
 const endpoint=`/api/vendor/business/${businessId}/waivers`;
 async function load(){const response=await fetch(endpoint);const data=await response.json().catch(()=>null);if(!response.ok||!data?.documents)throw new Error(data?.error??"Waivers are temporarily unavailable.");setDocuments(data.documents);setServices(data.services);setLoaded(true);}
 useEffect(()=>{void load().catch(e=>setError(e.message));},[endpoint]);
 async function save(doc:Document,assignments:Assignment[],archived=doc.archived){setPending(true);setError("");setDocuments(current=>current.map(item=>item.id===doc.id?{...item,assignments,archived}:item));try{const response=await fetch(endpoint,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({waiverId:doc.id,assignments,archived})});const data=await response.json();if(!response.ok)throw new Error(data.error);await load();}catch(e){setDocuments(current=>current.map(item=>item.id===doc.id?doc:item));setError(e instanceof Error?e.message:"Could not save waiver.");}finally{setPending(false);}}
 return <section id="business-waivers" className="rounded-2xl border bg-white p-5"><h3 className="text-lg font-semibold">Waivers</h3><p className="mt-2 text-sm text-muted-foreground">Upload a PDF and choose the services or packages that require it. Customers must sign electronically before continuing to payment. Upload a new version when the document changes; signed versions are kept.</p>
 <form className="mt-4 flex flex-wrap items-end gap-3" onSubmit={async event=>{event.preventDefault();const form=event.currentTarget;setPending(true);setError("");try{const response=await fetch(endpoint,{method:"POST",body:new FormData(form)}),data=await response.json();if(!response.ok)throw new Error(data.error);form.reset();await load();}catch(e){setError(e instanceof Error?e.message:"Could not upload waiver.");}finally{setPending(false);}}}><label className="grid gap-1 text-sm">Waiver title<input name="title" required minLength={2} maxLength={120} placeholder="e.g. Aerial activity waiver" className="rounded-xl border px-3 py-2"/></label><label className="grid gap-1 text-sm">PDF · up to 4 MB<input name="file" type="file" accept="application/pdf" required className="max-w-64 text-sm"/></label><button disabled={pending} className="rounded-full border bg-[#f5e7e6] px-4 py-2 text-sm" type="submit">{pending?"Saving…":"Upload waiver"}</button></form>
 {error&&<p role="alert" className="mt-3 text-sm text-red-700">{error}</p>}{loaded&&!documents.length&&<p className="mt-4 text-sm text-muted-foreground">No waivers yet.</p>}
 <div className="mt-5 space-y-4">{documents.map(doc=><article key={doc.id} className="rounded-xl border p-4"><div className="flex flex-wrap items-center justify-between gap-3"><h4 className="font-semibold">{doc.title}{doc.archived?" · Archived":""}</h4><div className="flex gap-3 text-sm"><a className="underline" href={`/api/waivers/${doc.id}`} target="_blank" rel="noreferrer">View PDF</a><button type="button" disabled={pending} onClick={()=>void save(doc,doc.assignments,!doc.archived)} className="underline">{doc.archived?"Restore":"Archive"}</button></div></div>{!doc.archived&&<fieldset disabled={pending} className="mt-3 space-y-3"><legend className="text-sm text-muted-foreground">Require this waiver for:</legend>{services.map(service=><div key={service.id} className="space-y-2"><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={doc.assignments.some(row=>row.offeringId===service.id&&!row.packageId)} onChange={event=>void save(doc,event.target.checked?[...doc.assignments.filter(row=>row.offeringId!==service.id),{offeringId:service.id,packageId:""}]:doc.assignments.filter(row=>row.offeringId!==service.id))}/>{service.title} · all packages</label>{service.packages.map(pkg=><label key={pkg.id} className="ml-6 flex items-center gap-2 text-sm"><input type="checkbox" disabled={doc.assignments.some(row=>row.offeringId===service.id&&!row.packageId)} checked={doc.assignments.some(row=>row.offeringId===service.id&&(!row.packageId||row.packageId===pkg.id))} onChange={event=>void save(doc,event.target.checked?[...doc.assignments,{offeringId:service.id,packageId:pkg.id}]:doc.assignments.filter(row=>row.offeringId!==service.id||row.packageId!==pkg.id))}/>{pkg.name}</label>)}</div>)}{!services.length&&<p className="text-sm">Create a service first, then attach this waiver.</p>}</fieldset>}{doc.signatures.length>0&&<details className="mt-4 text-sm"><summary>Signed copies ({doc.signatures.length})</summary><ul className="mt-2 space-y-2">{doc.signatures.map(signature=><li key={signature.id}><a className="underline" href={`/waivers/receipt/${signature.id}`} target="_blank" rel="noreferrer">{signature.signerName} · {new Date(signature.signedAt).toLocaleDateString()}</a></li>)}</ul></details>}</article>)}</div></section>;
}
